import{_ as a,o as t,c as o,a5 as s}from"./chunks/framework.C588jwcu.js";const u=JSON.parse('{"title":"씬 기반 리소스","description":"","frontmatter":{"title":"씬 기반 리소스","order":8},"headers":[],"relativePath":"ko/latest/tutorial/core/scene-assets.md","filePath":"ko/latest/tutorial/core/scene-assets.md","lastUpdated":1785683504000}'),c={name:"ko/latest/tutorial/core/scene-assets.md"};function r(d,e,n,_,i,l){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="씬-기반-리소스" tabindex="-1">씬 기반 리소스 <a class="header-anchor" href="#씬-기반-리소스" aria-label="Permalink to &quot;씬 기반 리소스&quot;">​</a></h1><p>캐릭터와 배경 항목은 <code>PackedScene</code>을 참조합니다. 씬에는 이미지, 비디오, Spine, Live2D, 셰이더 또는 사용자 노드를 넣을 수 있습니다.</p><p>캐릭터 씬은 <code>KND_CharacterSceneBase</code>를 상속하고 <code>_apply_status(resolved_status_name, original_status_name)</code>를 재정의합니다. 시스템은 <code>apply_status(status_name)</code>를 통해 이 메서드를 호출합니다. 기본적으로 <code>actor change</code>는 캐릭터 마운트를 페이드아웃하고 상태를 적용한 뒤 페이드인하며, 캐릭터 씬을 복제하지 않습니다. 전환이 끝난 뒤 스토리 실행을 계속합니다. 설정 방법은 <a href="./../script/actor/actor-change-state.html">액터 상태 전환</a>을 참고하세요. 무대 동작은 KS 동작 이름과 같은 애니메이션을 가진 <code>KND_ActorMotionLayer</code> 씬에 둡니다.</p><p>배경 씬은 <code>KND_BackgroundSceneBase</code>를 상속합니다. 카메라 명령을 사용하려면 고유한 이름의 <code>KonadoCamera2D</code>를 추가하세요. 기본 전환은 <code>KND_BackgroundTransitionLayer</code>가 처리합니다.</p>',4)])])}const m=a(c,[["render",r]]);export{u as __pageData,m as default};
